const i="/api";async function a(n,t){const e=await n.text();let r=null;if(e)try{r=JSON.parse(e)}catch{throw n.ok?new Error(`${t}（服务返回了无法解析的响应）`):new Error(`${t}（服务返回了非 JSON 响应，通常表示后端未启动或代理失败）`)}if(!n.ok){const o=r;throw new Error((o==null?void 0:o.error)||t)}if(!r)throw new Error(`${t}（服务返回空响应，通常表示后端未启动或代理失败）`);return r}async function c(n){const t=await fetch(`${i}/manage/auth/register`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(n)});return a(t,"注册失败")}async function h(n){const t=await fetch(`${i}/manage/auth/login`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(n)});return a(t,"登录失败")}export{h as l,c as r};
